def seed(apps, schema_editor):
    ContractTemplate = apps.get_model("contracts", "ContractTemplate")
    for data in SEED_TEMPLATES:
        ContractTemplate.objects.get_or_create(title=data["title"], defaults=data)


def unseed(apps, schema_editor):
    ContractTemplate = apps.get_model("contracts", "ContractTemplate")
    ContractTemplate.objects.filter(title__in=[t["title"] for t in SEED_TEMPLATES]).delete()


